BEGIN;
CREATE TABLE runtime_meta.business_partner_definition_bundle (
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,revision_id uuid NOT NULL,release_id uuid NOT NULL,release_no bigint NOT NULL,
 publication_key text NOT NULL,plane_code text NOT NULL,bundle_code text NOT NULL,semantic_version text NOT NULL,bundle_schema_version text NOT NULL,
 bundle_hash text NOT NULL,bundle_json jsonb NOT NULL,applied_release_id uuid NOT NULL UNIQUE,generated_at timestamptz NOT NULL,
 received_at timestamptz NOT NULL DEFAULT clock_timestamp(),status text NOT NULL DEFAULT 'staged',activated_at timestamptz,retired_at timestamptz,
 CONSTRAINT runtime_bp_definition_bundle_release_uq UNIQUE(tenant_id,bundle_code,release_id,plane_code),
 CONSTRAINT runtime_bp_definition_bundle_tenant_fk FOREIGN KEY(tenant_id) REFERENCES master.tenant(id) ON DELETE RESTRICT,
 CONSTRAINT runtime_bp_definition_bundle_applied_fk FOREIGN KEY(applied_release_id) REFERENCES runtime_meta.applied_release(id) ON DELETE RESTRICT,
 CONSTRAINT runtime_bp_definition_bundle_chk CHECK(release_no>=1 AND plane_code IN('studio','neon','mesh') AND bundle_code ~ '^[a-z][a-z0-9_.-]{1,126}$' AND semantic_version ~ '^[0-9]+\.[0-9]+\.[0-9]+([+-][A-Za-z0-9.-]+)?$' AND bundle_schema_version ~ '^[0-9]+\.[0-9]+\.[0-9]+$' AND bundle_hash ~ '^[a-f0-9]{64}$' AND jsonb_typeof(bundle_json)='object' AND bundle_json->>'schema'='athyper.business-partner-definition-bundle.v1'),
 CONSTRAINT runtime_bp_definition_bundle_status_chk CHECK((status='staged' AND activated_at IS NULL AND retired_at IS NULL) OR(status='active' AND activated_at IS NOT NULL AND retired_at IS NULL) OR(status='retired' AND activated_at IS NOT NULL AND retired_at IS NOT NULL AND retired_at>=activated_at))
);
CREATE INDEX runtime_bp_definition_bundle_release_idx ON runtime_meta.business_partner_definition_bundle(publication_key,release_no DESC);
CREATE UNIQUE INDEX runtime_bp_definition_bundle_active_uq ON runtime_meta.business_partner_definition_bundle(tenant_id,bundle_code,plane_code) WHERE status='active';

CREATE FUNCTION runtime_meta.fn_stage_business_partner_definition(p_applied_release_id uuid,p_projection jsonb) RETURNS runtime_meta.business_partner_definition_bundle LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,runtime_meta AS $$
DECLARE v_release runtime_meta.applied_release%ROWTYPE;v_row runtime_meta.business_partner_definition_bundle%ROWTYPE;v_plane text;
BEGIN
 IF jsonb_typeof(p_projection)<>'object' OR jsonb_typeof(p_projection->'bundle_json')<>'object' THEN RAISE EXCEPTION 'BUSINESS_PARTNER_DEFINITION_PROJECTION_INVALID' USING ERRCODE='check_violation';END IF;
 SELECT * INTO STRICT v_release FROM runtime_meta.applied_release WHERE id=p_applied_release_id FOR UPDATE;v_plane:=p_projection->>'plane_code';
 IF current_setting('app.database_plane',true) IS NOT NULL AND current_setting('app.database_plane',true)<>v_plane THEN RAISE EXCEPTION 'BUSINESS_PARTNER_DEFINITION_PLANE_MISMATCH' USING ERRCODE='check_violation';END IF;
 IF (p_projection->>'release_id')::uuid<>v_release.source_release_id OR (p_projection->>'release_no')::bigint<>v_release.source_release_no OR p_projection->>'publication_key'<>v_release.publication_key THEN RAISE EXCEPTION 'BUSINESS_PARTNER_DEFINITION_COORDINATE_MISMATCH' USING ERRCODE='check_violation';END IF;
 INSERT INTO runtime_meta.business_partner_definition_bundle(id,tenant_id,revision_id,release_id,release_no,publication_key,plane_code,bundle_code,semantic_version,bundle_schema_version,bundle_hash,bundle_json,applied_release_id,generated_at)
 VALUES((p_projection->>'id')::uuid,(p_projection->>'tenant_id')::uuid,(p_projection->>'revision_id')::uuid,(p_projection->>'release_id')::uuid,(p_projection->>'release_no')::bigint,p_projection->>'publication_key',v_plane,p_projection->>'bundle_code',p_projection->>'semantic_version',p_projection->>'bundle_schema_version',p_projection->>'bundle_hash',p_projection->'bundle_json',v_release.id,(p_projection->>'generated_at')::timestamptz) ON CONFLICT(id) DO NOTHING;
 SELECT * INTO STRICT v_row FROM runtime_meta.business_partner_definition_bundle WHERE id=(p_projection->>'id')::uuid;
 IF ROW(v_row.applied_release_id,v_row.bundle_hash,v_row.bundle_json,v_row.plane_code) IS DISTINCT FROM ROW(v_release.id,p_projection->>'bundle_hash',p_projection->'bundle_json',v_plane) THEN RAISE EXCEPTION 'BUSINESS_PARTNER_DEFINITION_IDEMPOTENCY_CONFLICT' USING ERRCODE='unique_violation';END IF;RETURN v_row;
END $$;

CREATE OR REPLACE FUNCTION runtime_meta.fn_stage_release_projection(p_publication_key text,p_source_release_id uuid,p_source_release_no bigint,p_deployment_id uuid,p_artifact_hash text,p_manifest jsonb,p_projection jsonb DEFAULT NULL) RETURNS runtime_meta.applied_release LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,runtime_meta AS $$
DECLARE v_release runtime_meta.applied_release%ROWTYPE;BEGIN v_release:=runtime_meta.fn_stage_release(p_publication_key,p_source_release_id,p_source_release_no,p_deployment_id,p_artifact_hash,p_manifest);IF p_projection?'business_partner_definition' THEN PERFORM runtime_meta.fn_stage_business_partner_definition(v_release.id,p_projection->'business_partner_definition');ELSIF p_projection IS NOT NULL THEN PERFORM runtime_meta.fn_stage_entity_projection(v_release.id,p_projection);END IF;RETURN v_release;END $$;

CREATE FUNCTION runtime_meta.trg_validate_business_partner_definition_release() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,runtime_meta AS $$
DECLARE b runtime_meta.business_partner_definition_bundle%ROWTYPE;e jsonb;
BEGIN
 IF NEW.publication_key NOT LIKE 'studio.business_partner.definition.%' THEN RETURN NEW;END IF;
 SELECT * INTO b FROM runtime_meta.business_partner_definition_bundle WHERE applied_release_id=NEW.id;e:=NEW.verification_evidence;
 IF NEW.status='verified' AND (b.id IS NULL OR e->>'target_plane' IS DISTINCT FROM b.plane_code OR e->>'definition_bundle_hash' IS DISTINCT FROM b.bundle_hash OR e->>'definition_bundle_schema_version' IS DISTINCT FROM b.bundle_schema_version) THEN RAISE EXCEPTION 'BUSINESS_PARTNER_DEFINITION_VERIFICATION_MISMATCH' USING ERRCODE='check_violation';END IF;
 IF NEW.status='superseded' THEN UPDATE runtime_meta.business_partner_definition_bundle SET status='retired',retired_at=clock_timestamp() WHERE applied_release_id=NEW.id AND status='active';END IF;
 IF NEW.status='active' THEN UPDATE runtime_meta.business_partner_definition_bundle SET status='retired',retired_at=clock_timestamp() WHERE tenant_id=b.tenant_id AND bundle_code=b.bundle_code AND plane_code=b.plane_code AND status='active' AND applied_release_id<>NEW.id;UPDATE runtime_meta.business_partner_definition_bundle SET status='active',activated_at=COALESCE(NEW.activated_at,clock_timestamp()),retired_at=NULL WHERE applied_release_id=NEW.id AND status IN('staged','retired');END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER runtime_bp_definition_release_guard AFTER UPDATE OF status ON runtime_meta.applied_release FOR EACH ROW EXECUTE FUNCTION runtime_meta.trg_validate_business_partner_definition_release();
CREATE FUNCTION runtime_meta.trg_guard_business_partner_definition_bundle() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Business Partner definition bundles are immutable' USING ERRCODE='restrict_violation';END IF;IF ROW(NEW.id,NEW.tenant_id,NEW.revision_id,NEW.release_id,NEW.release_no,NEW.publication_key,NEW.plane_code,NEW.bundle_code,NEW.semantic_version,NEW.bundle_schema_version,NEW.bundle_hash,NEW.bundle_json,NEW.applied_release_id,NEW.generated_at,NEW.received_at) IS DISTINCT FROM ROW(OLD.id,OLD.tenant_id,OLD.revision_id,OLD.release_id,OLD.release_no,OLD.publication_key,OLD.plane_code,OLD.bundle_code,OLD.semantic_version,OLD.bundle_schema_version,OLD.bundle_hash,OLD.bundle_json,OLD.applied_release_id,OLD.generated_at,OLD.received_at) THEN RAISE EXCEPTION 'Business Partner definition bundle content is immutable' USING ERRCODE='integrity_constraint_violation';END IF;RETURN NEW;END $$;
CREATE TRIGGER runtime_bp_definition_bundle_immutable BEFORE UPDATE OR DELETE ON runtime_meta.business_partner_definition_bundle FOR EACH ROW EXECUTE FUNCTION runtime_meta.trg_guard_business_partner_definition_bundle();
CREATE FUNCTION runtime_meta.fn_active_business_partner_definition(p_publication_key text) RETURNS SETOF runtime_meta.business_partner_definition_bundle LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,runtime_meta AS $$ SELECT b.* FROM runtime_meta.release_activation_head h JOIN runtime_meta.applied_release a ON a.id=h.applied_release_id AND a.status='active' JOIN runtime_meta.business_partner_definition_bundle b ON b.applied_release_id=a.id AND b.status='active' WHERE h.publication_key=p_publication_key $$;

ALTER TABLE runtime_meta.business_partner_definition_bundle ENABLE ROW LEVEL SECURITY;ALTER TABLE runtime_meta.business_partner_definition_bundle FORCE ROW LEVEL SECURITY;
CREATE POLICY runtime_bp_definition_bundle_tenant_read ON runtime_meta.business_partner_definition_bundle FOR SELECT USING(tenant_id=shared.current_tenant_id_soft());CREATE POLICY runtime_bp_definition_bundle_seed_owner ON runtime_meta.business_partner_definition_bundle FOR ALL TO CURRENT_USER USING(true) WITH CHECK(true);
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='athyper_projection_applier') THEN EXECUTE 'CREATE POLICY runtime_bp_definition_bundle_applier ON runtime_meta.business_partner_definition_bundle FOR ALL TO athyper_projection_applier USING(true) WITH CHECK(true)';GRANT SELECT ON runtime_meta.business_partner_definition_bundle TO athyper_projection_applier;GRANT EXECUTE ON FUNCTION runtime_meta.fn_stage_business_partner_definition(uuid,jsonb),runtime_meta.fn_active_business_partner_definition(text) TO athyper_projection_applier;END IF;IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='athyperapp') THEN GRANT SELECT ON runtime_meta.business_partner_definition_bundle TO athyperapp;GRANT EXECUTE ON FUNCTION runtime_meta.fn_active_business_partner_definition(text) TO athyperapp;END IF;END $$;
REVOKE ALL ON runtime_meta.business_partner_definition_bundle FROM PUBLIC;REVOKE ALL ON FUNCTION runtime_meta.fn_stage_business_partner_definition(uuid,jsonb),runtime_meta.fn_active_business_partner_definition(text),runtime_meta.trg_guard_business_partner_definition_bundle(),runtime_meta.trg_validate_business_partner_definition_release() FROM PUBLIC;
COMMIT;
